    "article": "Artigo 251",
    "title": "Estatuto dos Servidores de SP (Lei 10.261/1968) - Artigo 251",
    "content": "A demissão a bem do serviço público será aplicada nos casos de: I - incontinência pública e escandalosa ou vício de jogos proibidos; II - prática de crimes contra a administração pública; III - abandono de cargo por mais de 30 dias consecutivos; IV - insubordinação grave no serviço; V - improbidade administrativa.",
